export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"guidelines-for-relationship-effectiveness-keeping-the-relationship-give-a-way-to-d7e2c7bd3f45\",\"title\":\"Guidelines for Relationship Effectiveness: Keeping the Relationship (GIVE) A way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE): (Be) Gentle\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9711],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/03-dbt-interpersonal-effectiveness-interpersonal-effectiveness-handout-6-guidelines-for-rela-5f66c6289f.json\",\"sha256\":\"5f66c6289f3e0b01135dc02daae622541719ae4f6077b1ed702623d4be5317a0\",\"domain\":\"dbt\",\"bytes\":5988},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/interpersonal-effectiveness-handout-6-guidelines-for-relationship-effectiveness-keeping-the--1ec14fc184.json\",\"sha256\":\"1ec14fc184715f23d121a91a369298d6f7a5ed96355d8325907a604da2bc509e\",\"domain\":\"dbt\",\"bytes\":5819}]},\"data\":{\"pages\":[{\"pdf_page\":152,\"book_page\":\"128\",\"text\":\"128\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nInterpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\\nGuidelines for Relationship Effectiveness:\\nKeeping\u00a0the\u00a0Relationship (GIVE)\\nA way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE):\\n(Be) Gentle\\n(Act) Interested\\nValidate\\n(Use an) Easy manner\\n(Be)Gentle\\nBe nice and respectful.\\nNo attacks:\\nNo verbal or physical attacks. No hitting, clenching fists. No harassment of any\\nkind. Express anger directly with words.\\nNo threats:\\nIf you have to describe painful consequences for not getting what you want,\\ndescribe them calmly and without exaggerating.\\nNo \u201cmanipulative\u201d statements, no hidden threats. No \u201cI\u2019ll kill myself if you .\u00a0.\u00a0. \u201d\\nTolerate a \u201cno.\u201d Stay in the discussion even if it gets painful. Exit gracefully.\\nNo judging:\\nNo moralizing. No \u201cIf you were a good person, you would .\u00a0.\u00a0. \u201d\\nNo \u201cYou should\u00a0.\u00a0.\u00a0. \u201d or \u201cYou shouldn\u2019t .\u00a0.\u00a0. \u201d Abandon blame.\\nNo sneering: No smirking, eye rolling, sucking teeth. No cutting off or walking away.\\nNo saying, \u201cThat\u2019s stupid, don\u2019t be sad,\u201d \u201cI don\u2019t care what you say.\u201d\\n(Act)Interested\\nListen and appear interested in the other person.\\nListen to the other person\u2019s point of view.\\nFace the person; maintain eye contact; lean toward the person rather than\\naway. Don\u2019t interrupt or talk over the person.\\nBe sensitive to the person\u2019s wish to have the discussion at a later time. Be\\npatient.\\nValidate\\nWith words and actions, show that you understand the other person\u2019s\\nfeelings and thoughts about the situation. See the world from the other person\u2019s\\npoint of view, and then say or act on what you see.\\n\u201cI realize this is hard for you, and .\u00a0.\u00a0. \u201d, \u201cI see that you are busy, and .\u00a0.\u00a0. \u201d\\nGo to a private place when the person is uncomfortable talking in a public\\nplace.\\n(Use an)\\nEasy manner\\nUse a little humor.\\nSmile. Ease the person along. Be light-hearted. Sweet-talk.\\nUse a \u201csoft sell\u201d over a \u201chard sell.\u201d Be \u201cpolitical.\u201d\\nLeave your attitude at the door.\\nOther ideas:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Interpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\",\"source_pdf_pages\":[152],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effectiveness_keeping_the_relationship_giv.json\",\"item_number\":\"6\",\"full_text\":\"\u00ab\\nInterpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\\nGuidelines for Relationship Effectiveness:\\nKeeping\u00a0the\u00a0Relationship (GIVE)\\nA way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE):\\n(Be) Gentle\\n(Act) Interested\\nValidate\\n(Use an) Easy manner\\n(Be)Gentle\\nBe nice and respectful.\\nNo attacks:\\nNo verbal or physical attacks. No hitting, clenching fists. No harassment of any\\nkind. Express anger directly with words.\\nNo threats:\\nIf you have to describe painful consequences for not getting what you want,\\ndescribe them calmly and without exaggerating.\\nNo \u201cmanipulative\u201d statements, no hidden threats. No \u201cI\u2019ll kill myself if you .\u00a0.\u00a0. \u201d\\nTolerate a \u201cno.\u201d Stay in the discussion even if it gets painful. Exit gracefully.\\nNo judging:\\nNo moralizing. No \u201cIf you were a good person, you would .\u00a0.\u00a0. \u201d\\nNo \u201cYou should\u00a0.\u00a0.\u00a0. \u201d or \u201cYou shouldn\u2019t .\u00a0.\u00a0. \u201d Abandon blame.\\nNo sneering: No smirking, eye rolling, sucking teeth. No cutting off or walking away.\\nNo saying, \u201cThat\u2019s stupid, don\u2019t be sad,\u201d \u201cI don\u2019t care what you say.\u201d\\n(Act)Interested\\nListen and appear interested in the other person.\\nListen to the other person\u2019s point of view.\\nFace the person; maintain eye contact; lean toward the person rather than\\naway. Don\u2019t interrupt or talk over the person.\\nBe sensitive to the person\u2019s wish to have the discussion at a later time. Be\\npatient.\\nValidate\\nWith words and actions, show that you understand the other person\u2019s\\nfeelings and thoughts about the situation. See the world from the other person\u2019s\\npoint of view, and then say or act on what you see.\\n\u201cI realize this is hard for you, and .\u00a0.\u00a0. \u201d, \u201cI see that you are busy, and .\u00a0.\u00a0. \u201d\\nGo to a private place when the person is uncomfortable talking in a public\\nplace.\\n(Use an)\\nEasy manner\\nUse a little humor.\\nSmile. Ease the person along. Be light-hearted. Sweet-talk.\\nUse a \u201csoft sell\u201d over a \u201chard sell.\u201d Be \u201cpolitical.\u201d\\nLeave your attitude at the door.\\nOther ideas:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"I. E. Worksheets 4, 5\"],\"id\":\"interpersonal_effectiveness_handout_6\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"128\"],\"title\":\"Guidelines for Relationship Effectiveness: Keeping the Relationship (GIVE) A way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE): (Be) Gentle\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effecti_1826b8de.json\",\"module\":\"Interpersonal Effectiveness\",\"keywords\":[\"DEAR\",\"Effectiveness\",\"GIVE\",\"Gentle\",\"Guidelines\",\"Keeping\",\"Relationship\",\"remember\",\"skills\",\"these\",\"word\"]}}");
